contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 baseReserveSeed, uint256 baseTargetSeed) public payable {
        require(baseReserveSeed <= type(uint112).max);
        require(baseTargetSeed <= type(uint112).max);

        uint32 rBefore = c._RState_(); if (__ESBMC_reverted()) return;
        uint112 baseReserve = c._BASE_RESERVE_(); if (__ESBMC_reverted()) return;
        uint112 baseTargetBefore = c._BASE_TARGET_(); if (__ESBMC_reverted()) return;

        c.correctRState(); if (__ESBMC_reverted()) return;

        uint32 rAfter = c._RState_(); if (__ESBMC_reverted()) return;
        uint112 baseTargetAfter = c._BASE_TARGET_(); if (__ESBMC_reverted()) return;

        bool switchedBelowToOne =
            rBefore == uint32(2) &&
            rAfter == uint32(0) &&
            baseReserve < baseTargetBefore;

        assert(!switchedBelowToOne || baseTargetAfter == baseReserve);
    }

    receive() external payable {}
}

